let element = null;
let dotNetRef = null;
let timeoutMs = 0;
let timerId = null;
let controller = null;

const events = ["mousemove", "keydown", "click", "scroll", "touchstart"];

function handleActivity() {
    if (timerId !== null) {
        clearTimeout(timerId);
    } else {
        // Was idle, now active
        dotNetRef.invokeMethodAsync("OnUserActive");
    }
    timerId = setTimeout(() => {
        timerId = null;
        dotNetRef.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function initialize(el, ref, timeout) {
    element = el;
    dotNetRef = ref;
    timeoutMs = timeout;
    controller = new AbortController();

    for (const event of events) {
        element.addEventListener(event, handleActivity, { signal: controller.signal, passive: true });
    }

    // Start the initial idle timer
    timerId = setTimeout(() => {
        timerId = null;
        dotNetRef.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function dispose() {
    if (controller) {
        controller.abort();
        controller = null;
    }
    if (timerId !== null) {
        clearTimeout(timerId);
        timerId = null;
    }
    element = null;
    dotNetRef = null;
}

